import {dayKey,puzzleNumber,newGame,derive,arrange,submit,validGame,statistics,cleanHistory,TOTAL_PAIRS} from './engine.js';
import {LABELS} from './labels.js';
const $=s=>document.querySelector(s),KEY='timeline-v2';
let storageOK=true,today=dayKey(),mode='daily',selected=null,resultView='yours';
function read(k,f){let raw;try{raw=localStorage.getItem(k);}catch{storageOK=false;return f;}try{return JSON.parse(raw)??f;}catch{return f;}}
function write(k,v){try{localStorage.setItem(k,JSON.stringify(v));}catch{storageOK=false;}}
function loadDaily(){const seed=`daily:${today}`,g=read(`${KEY}:${today}`,null);return validGame(g,seed)?g:newGame(seed);}
const practiceSeed=()=> 'practice:'+(globalThis.crypto?.randomUUID?.()||`${Date.now()}-${Math.random()}`);
let daily=loadDaily(),practice=newGame(practiceSeed()),undo={daily:[],practice:[]},history=cleanHistory(read(KEY+'-history',{}));
const current=()=>mode==='daily'?daily:practice;
function setGame(g){if(mode==='daily'){daily=g;write(`${KEY}:${today}`,g);}else practice=g;}
function notify(text){$('#announcement').textContent=text;$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').classList.remove('visible'),2600);}
function saveResult(){const g=current(),s=derive(g);if(mode==='daily'&&g.submitted){history={...history,...cleanHistory(read(KEY+'-history',{})),[today]:s.result.correctPairs};write(KEY+'-history',history);}}
function dateChanged(){const next=dayKey();if(next===today)return false;today=next;daily=loadDaily();undo.daily=[];if(mode==='daily')selected=null;render();notify('A new daily timeline is ready.');return true;}
const letter=(cards,id)=>String.fromCharCode(65+cards.findIndex(c=>c.id===id));
function render(focus){
 const g=current(),s=derive(g),cards=s.cards,chosen=cards.find(c=>c.id===selected);
 const dateLabel=new Date(today+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'numeric',timeZone:'UTC'});
 $('#game').innerHTML=`${!storageOK?'<p class="storage-note">Progress cannot be saved in this browser right now. You can still play.</p>':''}
 <div class="edition-row"><div class="mode-switch" aria-label="Game mode"><button data-mode="daily" aria-pressed="${mode==='daily'}">Daily</button><button data-mode="practice" aria-pressed="${mode==='practice'}">Practice</button></div><p class="edition">${mode==='daily'?`NO. ${String(puzzleNumber(today)).padStart(3,'0')} <span>/</span> ${dateLabel}`:'PRACTICE <span>/</span> FREE PLAY'}</p></div>
 ${g.submitted?resultsMarkup(s):`<section class="puzzle-intro"><div><p class="eyebrow">The chronology is fractured</p><h1>Restore the timeline.</h1></div><button class="small-button" id="rules">How to play</button></section><p class="instruction">${chosen?`Tile ${letter(cards,selected)} selected. Tap a space to place or swap.`:'Tap a fragment, then a space. Arrange earliest to latest.'}</p>
 <div class="board"><section aria-label="Timeline spaces"><div class="column-label"><h2>Timeline</h2><span>Earliest ↓</span></div><ol class="timeline ${s.complete?'filled':''}">${s.ordered.map((card,i)=>`<li><span class="slot-number" aria-hidden="true">${String(i+1).padStart(2,'0')}</span><button class="slot ${card?'occupied':''} ${card?.id===selected?'selected':''} ${selected?'target':''}" data-slot="${i}" aria-label="Space ${i+1}${card?`: ${card.title}`:', empty'}${selected?', place selected tile here':''}" ${card?`aria-pressed="${card.id===selected}"`:''}>${card?`<span class="tile-letter">${letter(cards,card.id)}</span><span class="tile-title">${LABELS[card.id]||card.title}</span>`:'<span class="empty-glyph" aria-hidden="true">+</span><span class="empty-label">Place fragment</span>'}</button></li>`).join('')}</ol><p class="axis-end">Latest</p></section>
 <section aria-label="All event fragments"><div class="column-label"><h2>Fragments</h2><span>5 pieces</span></div><div class="fragments">${cards.map(card=>{const pos=g.slots.indexOf(card.id);return `<button class="fragment ${pos!==-1?'placed':''} ${selected===card.id?'selected':''}" data-tile="${card.id}" aria-pressed="${selected===card.id}" aria-label="Tile ${letter(cards,card.id)}: ${card.title}${pos!==-1?`, in space ${pos+1}`:''}"><span class="tile-letter">${letter(cards,card.id)}</span><span class="tile-title">${LABELS[card.id]||card.title}</span><span class="tile-meta">${pos!==-1?`In space ${pos+1} ↗`:card.category}</span></button>`;}).join('')}</div></section></div>
 <div class="board-tools"><button class="small-button" id="undo" ${undo[mode].length?'':'disabled'}>↶ Undo</button><span>${s.placed} of 5 placed</span><button class="small-button" id="return" ${selected&&g.slots.includes(selected)?'':'disabled'}>Return tile</button></div>
 <div class="submit-bar"><div class="submit-copy"><strong>${s.complete?'Ready to restore?':'Five fragments. One history.'}</strong><span>${s.complete?'You can still swap tiles before submitting.':'Years stay hidden until you submit.'}</span></div><button class="primary" id="submit" ${s.complete?'':'disabled'}>${s.complete?'Submit timeline':'Place all 5 tiles'} ↗</button></div>`}`;
 if(focus)$(focus)?.focus({preventScroll:true});
}
function resultsMarkup(s){const r=s.result,g=current(),order=resultView==='yours'?s.ordered:r.correctOrder;return `<section class="result-summary" tabindex="-1" id="result-summary"><p class="eyebrow">${r.percent===100?'Chronology complete':'Restoration report'}</p><h1>${r.percent===100?'Timeline restored.':r.percent===0?'Still fractured.':'History is reconnecting.'}</h1><div class="integrity"><strong>${r.percent}<span>%</span></strong><div><span class="integrity-label">Timeline integrity</span><p>${r.correctPairs} of ${r.totalPairs} pairs in the right order</p></div></div><div class="integrity-meter" aria-hidden="true">${Array.from({length:TOTAL_PAIRS},(_,i)=>`<span class="${i<r.correctPairs?'repaired':''}"></span>`).join('')}</div><p class="score-explanation">Every correctly ordered pair counts—even when a tile is in the wrong space. <button class="inline-button" id="scoring">How scoring works</button></p></section>
 <div class="result-actions"><button class="primary" id="share">Share result ↗</button><button class="secondary" id="new-practice">${mode==='daily'?'Try practice':'New timeline'}</button></div>
 <div class="review-heading"><h2>The revealed timeline</h2><div class="view-switch" aria-label="Result view"><button data-view="yours" aria-pressed="${resultView==='yours'}">Your order</button><button data-view="correct" aria-pressed="${resultView==='correct'}">Correct order</button></div></div>
 <ol class="revealed ${resultView==='correct'?'restored':''}">${order.map((card,i)=>{const rank=r.correctOrder.findIndex(c=>c.id===card.id),yourRank=g.slots.indexOf(card.id);return `<li><span class="reveal-index">${String(i+1).padStart(2,'0')}</span><details><summary><span class="reveal-year">${card.year}</span><span class="reveal-copy"><span>${card.title}</span><small>${resultView==='yours'?(rank===i?'✓ Exact position':`Correct position: ${rank+1}`):`Your position: ${yourRank+1}`} · ${card.category}</small></span><span class="expand" aria-hidden="true">+</span></summary><div class="event-fact"><p>${card.fact}</p><a href="${card.source}" target="_blank" rel="noopener noreferrer">Read about this moment ↗</a></div></details></li>`;}).join('')}</ol><p class="end-note">${mode==='daily'?'Daily result saved on this device. Another fracture appears at midnight UTC.':'Practice leaves your daily result and streak unchanged.'}</p>`;}
function changeTile(id,target){if(dateChanged()&&mode==='daily')throw new Error('The daily puzzle changed. Choose a tile from the new puzzle.');const g=current(),next=arrange(g,id,target);if(JSON.stringify(next.slots)!==JSON.stringify(g.slots)){undo[mode].push([...g.slots]);setGame(next);}selected=null;render(target===null?`[data-tile="${id}"]`:`[data-slot="${target}"]`);$('#announcement').textContent=target===null?'Tile returned to fragments.':`Tile placed in space ${target+1}.`;return publicState();}
function submitTimeline(){if(dateChanged()&&mode==='daily')throw new Error('A new daily puzzle is ready.');setGame(submit(current()));selected=null;undo[mode]=[];saveResult();resultView='yours';render('#result-summary');$('#result-summary').scrollIntoView({block:'start',behavior:'auto'});$('#announcement').textContent=`Timeline submitted. ${derive(current()).result.percent}% integrity.`;return publicState();}
function switchMode(next){if(!['daily','practice'].includes(next))throw new Error('Choose daily or practice.');mode=next;selected=null;resultView='yours';render(`[data-mode="${next}"]`);}
$('#game').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;try{
 if(b.dataset.mode){dateChanged();switchMode(b.dataset.mode);return;}
 if(b.dataset.view){resultView=b.dataset.view;render(`[data-view="${resultView}"]`);return;}
 if(b.dataset.tile){selected=selected===b.dataset.tile?null:b.dataset.tile;render(`[data-tile="${b.dataset.tile}"]`);$('#announcement').textContent=selected?'Tile selected. Choose a timeline space.':'Selection cleared.';return;}
 if(b.dataset.slot!==undefined){const i=Number(b.dataset.slot);if(selected)changeTile(selected,i);else if(current().slots[i]){selected=current().slots[i];render(`[data-slot="${i}"]`);}else notify('Choose a fragment first.');return;}
 if(b.id==='return'&&selected){changeTile(selected,null);return;}
 if(b.id==='undo'&&undo[mode].length){setGame({...current(),slots:undo[mode].pop()});selected=null;render('#undo');$('#announcement').textContent='Last move undone.';return;}
 if(b.id==='submit'){submitTimeline();return;}
 if(b.id==='new-practice'){practice=newGame(practiceSeed());undo.practice=[];switchMode('practice');window.scrollTo({top:0,behavior:'auto'});return;}
 if(b.id==='rules'){showRules();return;}if(b.id==='scoring'){showScoring();return;}
 if(b.id==='share'){const r=derive(current()).result;const text=`TIMELINE ${mode==='daily'?`#${puzzleNumber(today)} · ${today}`:'Practice'}\n${r.percent}% restored · ${r.correctPairs}/${r.totalPairs} pairs\n${'🟩'.repeat(r.correctPairs)}${'⬜'.repeat(r.totalPairs-r.correctPairs)}\n${location.origin}${location.pathname}`;try{await navigator.clipboard.writeText(text);notify('Result copied. Ready to share.');}catch{showModal('<h2>Share your restoration</h2><p>Copy your result below.</p><textarea id="share-text" aria-label="Result to copy" rows="6"></textarea>');$('#share-text').value=text;$('#share-text').select();}}
 }catch(error){notify(error.message);}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&selected){selected=null;render();}});
const modal=$('#modal');
function showModal(html){$('#modal-content').innerHTML=html;if(!modal.open)modal.showModal();}
function showRules(){showModal('<p class="eyebrow">Field guide / 01</p><h2>Put history back together.</h2><ol class="rules-list"><li><strong>Find your fragments.</strong> All five events are available from the start. Their dates are hidden.</li><li><strong>Rebuild the timeline.</strong> Tap a tile, then a space. Earliest at the top, latest at the bottom.</li><li><strong>Change your mind.</strong> Tap a placed tile and another space to move or swap it. Use Return tile or Undo whenever you need.</li><li><strong>Submit once.</strong> Place all five, then submit the whole timeline. Every year is revealed together.</li></ol><p>Every correctly ordered pair earns credit. The daily puzzle is shared worldwide and resets at midnight UTC. Practice as often as you like.</p>');}
function showScoring(){showModal('<p class="eyebrow">Field guide / 02</p><h2>Order matters.</h2><p>Five tiles make <strong>10 pairs</strong>. Each pair earns one point if its earlier event comes before its later event in your timeline.</p><p>If the correct order is <strong>A B C D E</strong>, and you submit <strong>E A B C D</strong>, the four relationships involving E are wrong. The six pairs among A, B, C, and D are still correct.</p><div class="score-example"><strong>6 / 10 pairs</strong><span>60% timeline integrity</span></div><p>Exact positions are shown for comparison after submission, but they do not determine your score. A reversed timeline scores 0%; a fully restored one scores 100%.</p>');}
$('#help-button').addEventListener('click',showRules);$('.close-dialog').addEventListener('click',()=>modal.close());
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}});
$('#stats-button').addEventListener('click',()=>{history=cleanHistory(read(KEY+'-history',history));const s=statistics(history,today);showModal(`<p class="eyebrow">Your restoration record</p><h2>A little order, daily.</h2><div class="stats-grid">${[[s.played,'Timelines completed'],[s.average===null?'—':s.average+'%','Average integrity'],[s.current,'Current streak'],[s.best,'Longest streak'],[s.perfect,'Fully restored']].map(([v,l])=>`<div class="stat"><strong>${v}</strong><span>${l}</span></div>`).join('')}</div><p>A streak counts consecutive daily submissions, at any score. Results stay in this browser. This scoring edition starts a fresh record; the earlier edition’s data is left untouched.</p>`);});
function tick(){dateChanged();const left=86400000-(Date.now()%86400000);$('#countdown').textContent=[Math.floor(left/3600000),Math.floor(left/60000)%60,Math.floor(left/1000)%60].map(n=>String(n).padStart(2,'0')).join(':');}
window.addEventListener('storage',e=>{if(e.key===`${KEY}:${today}`){daily=loadDaily();undo.daily=[];if(mode==='daily'){selected=null;render();}}if(e.key===KEY+'-history')history=cleanHistory(read(KEY+'-history',{}));});
document.addEventListener('visibilitychange',()=>{if(!document.hidden)tick();});
function publicState(){const s=derive(current());return {mode,date:today,submitted:s.submitted,tiles:s.cards.map(({id,title})=>({id,title})),slots:[...current().slots],...(s.submitted?{result:{percent:s.result.percent,correctPairs:s.result.correctPairs,totalPairs:s.result.totalPairs},correctOrder:s.result.correctOrder.map(({id,title,year})=>({id,title,year}))}:{})};}
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const entries=[
 {name:'read_timeline_game',description:'Read every tile and current space. Dates and scoring are hidden until submission.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:publicState},
 {name:'arrange_timeline_tile',description:'Stage a tile in a zero-based space, swapping placed tiles. Null returns it to the tray. Does not submit.',inputSchema:{type:'object',properties:{id:{type:'string'},space:{type:['integer','null'],minimum:0,maximum:4}},required:['id','space'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input.id!=='string')throw new Error('A tile ID is required.');return changeTile(input.id,input.space);}},
 {name:'submit_timeline',description:'Submit the complete five-tile order once, revealing all dates and the final score.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:submitTimeline}
 ];for(const entry of entries){try{Promise.resolve(document.modelContext.registerTool(entry,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
saveResult();render();tick();setInterval(tick,1000);

